import{_ as a,o as n,c as t,aN as e}from"./chunks/framework.D31DlcCL.js";const m="/img/math-area-calc.svg",g=JSON.parse('{"title":"小学奥数进阶：几何图形的面积巧算","description":"遇到不规则图形怎么办？本文教你使用平移、旋转、割补等几何变换技巧，将复杂的阴影面积转化为基础图形求解。","frontmatter":{"title":"小学奥数进阶：几何图形的面积巧算","date":"2026-02-08T11:30:00.000Z","categories":["数学"],"tags":["小学数学","奥数","面积计算"],"description":"遇到不规则图形怎么办？本文教你使用平移、旋转、割补等几何变换技巧，将复杂的阴影面积转化为基础图形求解。","cover":"/img/math-area-calc.svg","top_img":"/img/banner.svg","toc_number":true,"katex":true},"headers":[],"relativePath":"posts/primary-math-olympiad-area-calc-intro.md","filePath":"posts/primary-math-olympiad-area-calc-intro.md","lastUpdated":null}'),i={name:"posts/primary-math-olympiad-area-calc-intro.md"};function p(l,s,r,o,c,h){return n(),t("div",null,[...s[0]||(s[0]=[e('<h1 id="小学奥数进阶-几何图形的面积巧算" tabindex="-1">小学奥数进阶：几何图形的面积巧算 <a class="header-anchor" href="#小学奥数进阶-几何图形的面积巧算" aria-label="Permalink to &quot;小学奥数进阶：几何图形的面积巧算&quot;">​</a></h1><h2 id="一、-核心基础公式" tabindex="-1">一、 核心基础公式 <a class="header-anchor" href="#一、-核心基础公式" aria-label="Permalink to &quot;一、 核心基础公式&quot;">​</a></h2><p>在开始巧算之前，必须熟记基础公式：</p><ul><li><strong>长方形</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>S</mi><mo>=</mo><mi>a</mi><mo>×</mo><mi>b</mi></mrow><annotation encoding="application/x-tex">S = a \\times b</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.77777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05764em;">S</span><span class="mrel">=</span><span class="mord mathit">a</span><span class="mbin">×</span><span class="mord mathit">b</span></span></span></span></li><li><strong>正方形</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>S</mi><mo>=</mo><mi>a</mi><mo>×</mo><mi>a</mi></mrow><annotation encoding="application/x-tex">S = a \\times a</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.76666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05764em;">S</span><span class="mrel">=</span><span class="mord mathit">a</span><span class="mbin">×</span><span class="mord mathit">a</span></span></span></span></li><li><strong>三角形</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>S</mi><mo>=</mo><mi>a</mi><mo>×</mo><mi>h</mi><mo>÷</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">S = a \\times h \\div 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.77777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05764em;">S</span><span class="mrel">=</span><span class="mord mathit">a</span><span class="mbin">×</span><span class="mord mathit">h</span><span class="mbin">÷</span><span class="mord mathrm">2</span></span></span></span></li><li><strong>平行四边形</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>S</mi><mo>=</mo><mi>a</mi><mo>×</mo><mi>h</mi></mrow><annotation encoding="application/x-tex">S = a \\times h</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.77777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05764em;">S</span><span class="mrel">=</span><span class="mord mathit">a</span><span class="mbin">×</span><span class="mord mathit">h</span></span></span></span></li><li><strong>梯形</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>S</mi><mo>=</mo><mo>(</mo><mi>a</mi><mo>+</mo><mi>b</mi><mo>)</mo><mo>×</mo><mi>h</mi><mo>÷</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">S = (a + b) \\times h \\div 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05764em;">S</span><span class="mrel">=</span><span class="mopen">(</span><span class="mord mathit">a</span><span class="mbin">+</span><span class="mord mathit">b</span><span class="mclose">)</span><span class="mbin">×</span><span class="mord mathit">h</span><span class="mbin">÷</span><span class="mord mathrm">2</span></span></span></span></li></ul><hr><h2 id="二、-面积巧算四大法宝" tabindex="-1">二、 面积巧算四大法宝 <a class="header-anchor" href="#二、-面积巧算四大法宝" aria-label="Permalink to &quot;二、 面积巧算四大法宝&quot;">​</a></h2><h3 id="_1-割补法" tabindex="-1">1. 割补法 <a class="header-anchor" href="#_1-割补法" aria-label="Permalink to &quot;1. 割补法&quot;">​</a></h3><p>将图形切割开，再拼补到其他位置，使其变成规则图形。 <strong>例题</strong>：求一个大正方形里扣掉一个小正方形后的阴影面积。</p><ul><li><strong>思维</strong>：S_{阴影} = S_{大} - S_{小}。</li></ul><h3 id="_2-平移与旋转" tabindex="-1">2. 平移与旋转 <a class="header-anchor" href="#_2-平移与旋转" aria-label="Permalink to &quot;2. 平移与旋转&quot;">​</a></h3><p>通过平行移动或旋转某个部分，改变图形形状而不改变面积。</p><p><img src="'+m+'" alt="几何面积巧算图解"></p><h3 id="_3-等底等高模型-同底等高" tabindex="-1">3. 等底等高模型（同底等高） <a class="header-anchor" href="#_3-等底等高模型-同底等高" aria-label="Permalink to &quot;3. 等底等高模型（同底等高）&quot;">​</a></h3><ul><li><strong>结论 1</strong>：等底等高的两个三角形面积相等。</li><li><strong>结论 2</strong>：在平行线之间，所有底相等、高相等的三角形面积都一样。</li></ul><h3 id="_4-差值法-蝴蝶模型基础" tabindex="-1">4. 差值法（蝴蝶模型基础） <a class="header-anchor" href="#_4-差值法-蝴蝶模型基础" aria-label="Permalink to &quot;4. 差值法（蝴蝶模型基础）&quot;">​</a></h3><p><strong>例题</strong>：已知长方形内有两个交错的三角形，求阴影部分。</p><ul><li><strong>思维</strong>：利用 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>S</mi><mi>A</mi></msub><mo>−</mo><msub><mi>S</mi><mi>B</mi></msub><mo>=</mo><mo>(</mo><msub><mi>S</mi><mi>A</mi></msub><mo>+</mo><msub><mi>S</mi><mi>C</mi></msub><mo>)</mo><mo>−</mo><mo>(</mo><msub><mi>S</mi><mi>B</mi></msub><mo>+</mo><msub><mi>S</mi><mi>C</mi></msub><mo>)</mo></mrow><annotation encoding="application/x-tex">S_A - S_B = (S_A + S_C) - (S_B + S_C)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.05764em;">S</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.05764em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">A</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">−</span><span class="mord"><span class="mord mathit" style="margin-right:0.05764em;">S</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.05764em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit" style="margin-right:0.05017em;">B</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mopen">(</span><span class="mord"><span class="mord mathit" style="margin-right:0.05764em;">S</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.05764em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">A</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.05764em;">S</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.05764em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mclose">)</span><span class="mbin">−</span><span class="mopen">(</span><span class="mord"><span class="mord mathit" style="margin-right:0.05764em;">S</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.05764em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit" style="margin-right:0.05017em;">B</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.05764em;">S</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.05764em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mclose">)</span></span></span></span>，通过增加一个公共区域 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>C</mi></mrow><annotation encoding="application/x-tex">C</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span> 来简化计算。</li></ul><hr><h2 id="三、-典型案例解析" tabindex="-1">三、 典型案例解析 <a class="header-anchor" href="#三、-典型案例解析" aria-label="Permalink to &quot;三、 典型案例解析&quot;">​</a></h2><p><strong>例题</strong>：一个长方形长 10 厘米，宽 6 厘米。里面有一个阴影三角形，底边在长方形的长上，顶点在对边上。求阴影面积。</p><ul><li><strong>解析</strong>： <ul><li>三角形的底 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">= 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span> 厘米。</li><li>三角形的高 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo></mrow><annotation encoding="application/x-tex">=</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span></span></span></span> 长方形的宽 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">= 6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span> 厘米。</li><li>面积 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>1</mn><mn>0</mn><mo>×</mo><mn>6</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>3</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">= 10 \\times 6 \\div 2 = 30</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">6</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">0</span></span></span></span> 平方厘米。</li></ul></li><li><strong>结论</strong>：长方形内最大的三角形面积，正好是长方形面积的一半。</li></ul><hr><h2 id="四、-总结提升" tabindex="-1">四、 总结提升 <a class="header-anchor" href="#四、-总结提升" aria-label="Permalink to &quot;四、 总结提升&quot;">​</a></h2><ol><li><strong>化繁为简</strong>：把复杂的阴影看作几个简单图形的加减。</li><li><strong>寻找基准</strong>：找平行线、找直角、找相等的边。</li><li><strong>辅助线</strong>：有时连上一条对角线，问题就迎刃而解。</li></ol><hr><h2 id="五、-举一反三-练习题" tabindex="-1">五、 举一反三（练习题） <a class="header-anchor" href="#五、-举一反三-练习题" aria-label="Permalink to &quot;五、 举一反三（练习题）&quot;">​</a></h2><ol><li>一个等腰直角三角形的斜边长 8 厘米，求它的面积。</li><li>在一个半径为 5 厘米的圆内画一个最大的正方形，求正方形的面积。</li></ol><hr><p><em>提示：眼睛要学会“搬家”，把阴影搬到好算的地方去！</em></p>',29)])])}const u=a(i,[["render",p]]);export{g as __pageData,u as default};
